-- One-time import of the 97 hardcoded Fiverr testimonials into the reviews table,
-- as approved reviews, so the site can drop the hardcoded array and read purely from Supabase.
-- Run this once in the Supabase SQL editor.

with import_request as (
  insert into review_requests (client_name, used_at)
  values ('Historical import (Fiverr reviews)', now())
  returning id
)
insert into reviews (request_id, name, avatar_url, country, quote, rating, status, created_at)
select id, v.name, v.avatar_url, v.country, v.quote, v.rating, 'approved', v.created_at
